const stops=[
{name:'于都',sub:'中央红军长征出发地',date:'1934.10',lat:25.95,lon:115.42,img:'assets/archive/yudu.jpg',type:'影像复原',lead:'八万余名中央红军将士，从这里渡过于都河，把故乡留在身后。',story:'1934年10月，中共中央和中央红军主力陆续集结赣南于都。部队从多个渡口夜渡于都河，开始战略转移。为了隐蔽行动，当地群众帮助架设浮桥、筹集粮草、掩护渡河。出发时，许多人并不知道前路有多远。',detail:'于都河宽水急。百姓拆下自家门板、床板架桥，船工往返摆渡；为不暴露目标，浮桥通常白天拆除、夜间重架。告别发生在寂静之中，却由此开启了影响中国历史的远征。',meaning:'长征的第一步不是传奇，而是离开。战略转移保存革命力量的任务，从每一名战士跨上浮桥的那一刻开始。',place:'定位为江西省于都县中央红军长征出发地纪念园、渡口附近。坐标用于展陈定位。',source:'https://www.81.cn/2021zt/2021-10/17/content_10099972.htm'},
{name:'湘江',sub:'界首渡口与湘江战役',date:'1934.11—12',lat:25.78,lon:110.48,img:'assets/archive/xiangjiang.jpg',type:'纪念地影像',lead:'连续数日血战，湘江水曾被鲜血染红。中央红军付出了长征以来最惨重的代价。',story:'为突破国民党军第四道封锁线，中央红军在广西兴安、全州、灌阳一带与优势敌军激战。广大指战员以巨大牺牲掩护中央纵队渡过湘江。战后，中央红军由出发时的八万余人锐减至三万余人。',detail:'新圩、脚山铺、光华铺等阻击阵地鏖战惨烈。红三十四师承担后卫任务，大部壮烈牺牲。师长陈树湘重伤被俘后，以极其悲壮的方式践行了自己的誓言。',meaning:'惨重损失迫使全党全军反思原有军事指挥。血的代价，使改变错误路线、重建实事求是的指挥成为无法回避的历史要求。',place:'定位为广西兴安县界首镇湘江战役旧址、纪念设施附近。',source:'https://www.ynds.yn.gov.cn/html/zhongyanghongjunqiaodujinshajiang/2022/7/8/5b39519c-6ff1-4dc6-9b61-042094bb13d7.html'},
{name:'遵义',sub:'遵义会议会址',date:'1935.01',lat:27.69,lon:106.92,img:'assets/archive/zunyi.jpg',type:'会址今貌',lead:'一间并不宽敞的会议室，让中国革命在最危急的关头重新找到方向。',story:'1935年1月，中共中央政治局在遵义召开扩大会议，集中总结第五次反“围剿”失败和长征初期军事指挥的经验教训。会议开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位。',detail:'会议不是在条件完备时召开，而是在敌军逼近、部队亟待休整的危急行军途中进行。它以独立自主的方式解决中国革命自身的重大问题，是党在政治上走向成熟的重要标志。',meaning:'遵义会议证明，真正的道路不是照搬出来的，而是在实践与牺牲中检验、在直面错误中重新选择的。它挽救了党、挽救了红军、挽救了中国革命。',place:'定位为贵州省遵义市红花岗区遵义会议会址。',source:'https://www.81.cn/2021zt/2021-10/17/content_10099972.htm'},
{name:'赤水',sub:'土城渡口 · 四渡赤水',date:'1935.01—03',lat:28.29,lon:106.01,img:'assets/archive/chishui.jpg',type:'遗址今貌',lead:'在川黔滇交界的群山与河流间，红军把“被围追”变成“牵着敌人走”。',story:'土城战斗后，中央红军一渡赤水进入川南；随后根据敌情变化，二渡赤水回师黔北，重占遵义；再由茅台三渡赤水进入川南，继而秘密迅速四渡赤水，南渡乌江，直逼贵阳。',detail:'四次渡河并非预先写好的固定剧本。每一步都依赖对敌情、地形和时机的快速判断。红军时而向西、时而折返，以高度机动调动敌军，跳出重兵合围。',meaning:'这是实事求是、灵活机动的经典战例。困难不是靠口号化解，而是靠不断获取信息、修正判断，把主动权从绝境里一点点夺回来。',place:'定位为贵州省习水县土城镇赤水河渡口、四渡赤水纪念地附近。',source:'https://www.ynds.yn.gov.cn/html/zhongyanghongjunqiaodujinshajiang/2022/7/8/5b39519c-6ff1-4dc6-9b61-042094bb13d7.html'},
{name:'皎平渡',sub:'巧渡金沙江',date:'1935.05',lat:26.31,lon:102.91,img:'assets/archive/jiaoping.jpg',type:'遗址今貌',lead:'几只木船、三十多名船工，九天九夜，把数万红军送出包围圈。',story:'1935年4月底，中央红军决定抢渡金沙江。先遣部队在皎平渡找到船只并控制渡口。5月3日至9日，中央红军主力依靠有限船只昼夜渡江，等追敌赶到南岸时，红军主力已渡过金沙江。',detail:'没有宽阔桥梁，也没有现代机械。船工与红军战士轮班摆渡，渡口组织严密。渡江行动使敌军企图在金沙江以南围歼红军的计划落空。',meaning:'速度、纪律与军民协作在这里合为一体。所谓奇迹，背后是对渡口的侦察、对时间的精确利用，以及普通船工持续九昼夜的担当。',place:'定位为云南省禄劝县与四川省会理市交界的皎平渡渡口纪念地附近。',source:'https://www.81.cn/yljnt_208627/lsda_208656/16389771.html'},
{name:'泸定桥',sub:'飞夺泸定桥',date:'1935.05.29',lat:29.91,lon:102.23,img:'assets/archive/luding.jpg',type:'历史照片',lead:'二十二名勇士沿着只剩铁索的桥面向前，脚下是奔涌的大渡河，对岸是敌人的火力。',story:'红军强渡大渡河后，为迅速夺取泸定桥，红四团昼夜急行军赶到西岸。突击队冒着火力，攀踏铁索向对岸冲击；后续部队铺设桥板跟进，最终夺取泸定桥。',detail:'从接到命令到抵达泸定桥，部队在山路中急行军。桥板已被拆去大部，铁索下是湍急河水。突击与接应、火力掩护与铺板协同完成，任何一环中断都可能付出更大代价。',meaning:'勇气并非不知危险，而是清楚危险仍为全军打开通道。它也是组织、协同和纪律共同创造的勇敢。',place:'定位为四川省甘孜州泸定县泸定桥。',source:'https://photo.81.cn/zhuanti/gwwycz.htm'},
{name:'夹金山',sub:'翻越第一座大雪山',date:'1935.06',lat:30.95,lon:102.71,img:'assets/archive/jiajin.jpg',type:'遗址今貌',lead:'空气稀薄、风雪刺骨。没有足够御寒装备，战士们仍然翻过海拔四千米以上的雪线。',story:'1935年6月，中央红军翻越夹金山。这里山势高峻、气候多变，是中央红军长征途中翻越的第一座大雪山。部队缺少御寒衣物和高原行军经验，饥饿、低温与缺氧同时袭来。',detail:'夹金山平均海拔在四千米以上，主峰海拔约5240米。山上天气瞬息变化，积雪、冰雹与强风让停留都变得危险。有人把仅有的辣椒、衣物让给战友，也有人永远留在雪地里。',meaning:'雪山没有被“征服”，它见证的是人在极端自然面前彼此支撑。把生的机会让给战友，是长征精神最沉默也最有重量的部分。',place:'定位为四川省雅安市宝兴县夹金山垭口、纪念地附近。',source:'https://www.81.cn/wh_208594/16466170.html'},
{name:'草地',sub:'若尔盖草地 · 班佑',date:'1935.08',lat:33.58,lon:102.96,img:'assets/archive/grassland.jpg',type:'纪念地今貌',lead:'看似平坦的草甸下，是会吞没人的泥沼。方向、粮食与体力同时耗尽。',story:'红军穿越的松潘草地位于青藏高原与四川盆地连接地带，水草盘结、沼泽密布，天气变化剧烈。行军部队常常看不见明确道路，只能凭经验与前队痕迹前进。',detail:'草根、皮带甚至皮革制品都曾成为充饥之物。夜间无处宿营，队伍只能在湿地间寻找稍硬的草墩。饥饿、疾病、低温和迷路造成严重减员，人与人之间的搀扶成为穿越的关键。',meaning:'草地没有冲锋号，却是一场持续多日的生命考验。坚持并非孤立的个人意志，而是把仅有食物分给战友、把倒下的人重新扶起。',place:'定位为四川省阿坝州若尔盖县班佑、红军过草地纪念区域附近。',source:'https://www.81.cn/yw_208727/16488774.html'},
{name:'腊子口',sub:'突破天险腊子口',date:'1935.09',lat:34.14,lon:103.90,img:'assets/archive/lazikou.jpg',type:'遗址今貌',lead:'峭壁夹着狭窄隘口，正面受阻的红军从悬崖侧后打开了通往陕甘的门户。',story:'腊子口是川西北通往甘南的重要隘口，两侧峭壁陡立，正面通道狭窄。守军凭险封锁。红军一面正面进攻，一面组织力量攀登峭壁、迂回侧后，最终突破天险。',detail:'正面桥头火力封锁严密，常规强攻代价极大。战士借助山势从难以想象的路线攀援，形成前后夹击。突破后，中央红军得以进入甘南，打开北上的通道。',meaning:'当所有人都盯着唯一的门，真正的突破可能来自悬崖。勇猛与创造不是两种精神，而是在绝境中互相成就。',place:'定位为甘肃省甘南州迭部县腊子口战役遗址附近。',source:'https://www.81.cn/2021zt/2021-10/17/content_10099972.htm'},
{name:'吴起镇',sub:'中央红军到达陕北',date:'1935.10',lat:36.92,lon:108.18,img:'assets/archive/wuqi.jpg',type:'遗址今貌',lead:'陕北的山梁出现在眼前时，中央红军历时一年的长途转战迎来新的落脚点。',story:'1935年10月，中央红军到达陕北吴起镇，同陕甘革命根据地红军胜利会师。随后通过战斗击退尾追之敌，中央红军长征胜利结束，中国革命由此获得新的立足点。',detail:'到达不是轻松的终点。队伍经长期行军已经严重减员、极度疲惫，仍需应对尾追。陕北根据地军民的接应，使远征的队伍第一次真切触到新的落脚处。',meaning:'长征保存了革命的火种，也把分散的力量重新汇聚。吴起镇所代表的，不只是“终于抵达”，更是从这里再次出发。',place:'定位为陕西省延安市吴起县中央红军长征胜利纪念园、旧址附近。',source:'https://www.81.cn/2021zt/2021-10/17/content_10099972.htm'},
{name:'会宁',sub:'红军三大主力会师',date:'1936.10',lat:35.69,lon:105.05,img:'assets/archive/huining.jpg',type:'会师旧址今貌',lead:'三支远征的队伍在西北大地上会合，历时两年的战略转移宣告胜利。',story:'1936年10月，红一、红二、红四方面军在甘肃会宁及将台堡地区胜利会师。三大主力会师标志着具有伟大历史意义的长征胜利结束，中国革命进入新的阶段。',detail:'不同部队走过不同路线，经历雪山草地、战斗与饥饿。会师时，战士们相拥、握手、交换沿途故事。胜利不是某一个人的抵达，而是分散力量重新汇成洪流。',meaning:'长征以会师完成空间上的汇聚，也完成信念上的证明：只要理想仍在、队伍仍在、人民仍在，最艰难的路就能成为新的起点。',place:'定位为甘肃省白银市会宁县红军会宁会师旧址。',source:'https://www.81.cn/js_208592/9978119.html'}
];

const scenarios=[
{title:'湘江之后：继续原定方向，还是改变？',date:'1934年12月 · 通道地区',bg:'assets/archive/xiangjiang.jpg',situation:'部队刚刚付出惨重代价。前方敌军已布下重兵，原定会合方向暴露；后有追兵，时间极少。你所掌握的情报并不完整。',choices:['仍按原计划北上，与红二、六军团会合','转向敌军力量薄弱的贵州，争取主动','原地休整，等待后续情报'],correct:1,answer:'历史选择：转兵贵州',explain:'通道会议前后，毛泽东力主放弃已被敌军判明的原定方向，向敌军力量相对薄弱的贵州前进。部队随后占领黎平、渡过乌江并攻克遵义，为召开遵义会议赢得空间。'},
{title:'赤水河畔：计划已变，要不要再变？',date:'1935年2月 · 川黔边界',bg:'assets/archive/chishui.jpg',situation:'敌军根据你的上一轮行动重新部署，原计划的突破口已不再有利。部队连续行军，任何折返都会增加体力消耗，但固守计划可能陷入合围。',choices:['坚持既定路线，避免队伍混乱','根据敌情立即折返，寻找新的空隙','分散行动，各部自行突围'],correct:1,answer:'历史选择：因敌而变，四渡赤水',explain:'四渡赤水的精髓不是路线本身，而是不断依据敌情改变行动。红军以高度机动制造错觉，调动敌军，在运动中从被动转为主动，最终跳出包围。'},
{title:'雪山草地：仅有的食物该给谁？',date:'1935年夏 · 川西北',bg:'assets/archive/grassland.jpg',situation:'粮食几乎耗尽。一名战友体力不支，你也已经连续多日没有吃饱。前方仍不知还有几天路程。留下食物是本能，分出去也许意味着共同的风险。',choices:['保留自己的口粮，先确保能继续行军','平均分给同行战友，彼此搀扶前进','交给队伍中最虚弱的人'],correct:2,answer:'历史里没有唯一标准答案',explain:'长征途中留下许多把粮食、衣物甚至生的机会让给战友的故事。真正支撑队伍走出绝境的，不是孤立的个人强壮，而是纪律、互助和把他人生命放在心上的选择。'}
];

const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];let activeStop=0,activeScenario=0,currentRoom='prologue',spirit='信仰';
function enter(withSound){$('#entry').classList.add('exit');$('#exhibition').classList.add('ready');$('#exhibition').setAttribute('aria-hidden','false');if(withSound) startAudio();setTimeout(()=>animateCounts(),500)}
$('#enterSound').onclick=()=>enter(true);$('#enterSilent').onclick=()=>enter(false);$$('[data-enter]').forEach(b=>b.onclick=()=>enter(false));
function showRoom(name){currentRoom=name;$$('.room').forEach(r=>r.classList.toggle('active',r.dataset.roomName===name));$$('[data-room]').forEach(b=>b.classList.toggle('active',b.dataset.room===name));$('.main-nav').classList.remove('open');if(name==='archive') setTimeout(updateArchiveProgress,100)}
$$('[data-room]').forEach(b=>b.addEventListener('click',()=>showRoom(b.dataset.room)));$('#menuBtn').onclick=()=>$('.main-nav').classList.toggle('open');
document.addEventListener('pointermove',e=>{const c=$('.cursor-light');c.style.left=e.clientX+'px';c.style.top=e.clientY+'px'});
function animateCounts(){$$('[data-count]').forEach(el=>{const goal=+el.dataset.count,start=performance.now(),dur=1400;requestAnimationFrame(function tick(now){const p=Math.min(1,(now-start)/dur),v=Math.floor(goal*(1-Math.pow(1-p,3)));el.textContent=v.toLocaleString()+(goal===380?'+':'');if(p<1)requestAnimationFrame(tick)})})}

function project(s){const minLon=101,maxLon=116,minLat=24.8,maxLat=37.4;return{x:110+(maxLon-s.lon)/(maxLon-minLon)*760,y:545-(s.lat-minLat)/(maxLat-minLat)*430}}
const pts=stops.map(project);const d=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' ');$('#routePath').setAttribute('d',d);$('#routeShadow').setAttribute('d',d);
stops.forEach((s,i)=>{const p=pts[i],g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','map-node'+(i===0?' active':''));g.dataset.index=i;g.innerHTML=`<circle class="outer" cx="${p.x}" cy="${p.y}" r="11"/><circle class="inner" cx="${p.x}" cy="${p.y}" r="4"/><text x="${p.x+15}" y="${p.y+5}">${s.name}</text>`;g.onclick=()=>selectStop(i);$('#mapNodes').append(g);const chip=document.createElement('button');chip.className='route-chip'+(i===0?' active':'');chip.dataset.index=i;chip.innerHTML=`<span>${String(i+1).padStart(2,'0')} · ${s.date}</span><b>${s.name}</b>`;chip.onclick=()=>selectStop(i);$('#routeScroll').append(chip)});
function selectStop(i){activeStop=(i+stops.length)%stops.length;const s=stops[activeStop];$$('.map-node').forEach((n,j)=>n.classList.toggle('active',j===activeStop));$$('.route-chip').forEach((n,j)=>n.classList.toggle('active',j===activeStop));const chip=$(`.route-chip[data-index="${activeStop}"]`);chip?.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'});$('#mapCoordinate').textContent=`${s.lat.toFixed(2)}°N · ${s.lon.toFixed(2)}°E`;$('#routeFocus').innerHTML=`<small>${String(activeStop+1).padStart(2,'0')} / 11 · ${s.sub}</small><h3>${s.name}</h3><span class="focus-date">${s.date}</span><p>${s.lead}</p><button onclick="openDetail(${activeStop})">进入历史现场 →</button>`}
selectStop(0);$('#routePrev').onclick=()=>selectStop(activeStop-1);$('#routeNext').onclick=()=>selectStop(activeStop+1);

const wall=$('#archiveWall');stops.forEach((s,i)=>{const a=document.createElement('article');a.className='archive-item';a.innerHTML=`<img src="${s.img}" alt="${s.name}相关${s.type}" loading="lazy"><div class="archive-index">${String(i+1).padStart(2,'0')}</div><div class="archive-caption"><small>${s.type}</small><h3>${s.name}</h3><p>${s.date} · ${s.sub}</p></div>`;a.onclick=()=>openDetail(i);wall.append(a)});function updateArchiveProgress(){const max=wall.scrollWidth-wall.clientWidth;$('#archiveProgress').style.width=(max?20+80*wall.scrollLeft/max:100)+'%'}wall.addEventListener('scroll',updateArchiveProgress,{passive:true});wall.addEventListener('wheel',e=>{if(Math.abs(e.deltaY)>Math.abs(e.deltaX)){wall.scrollLeft+=e.deltaY;e.preventDefault()}},{passive:false});

function openDetail(i){activeStop=i;const s=stops[i];$('#detailImage').src=s.img;$('#detailImage').alt=s.name+s.type;$('#detailImageType').textContent=s.type;$('#detailIndex').textContent=String(i+1).padStart(2,'0');$('#detailDate').textContent=s.date;$('#detailCoord').textContent=`约 ${s.lat.toFixed(2)}°N / ${s.lon.toFixed(2)}°E`;$('#detailTitle').textContent=s.name;$('#detailSubtitle').textContent=s.sub;$('#detailLead').textContent=s.lead;$('#detailStory').textContent=s.story;$('#detailDetail').textContent=s.detail;$('#detailMeaning').textContent=s.meaning;$('#detailPlace').textContent=s.place;$('#detailSource').href=s.source;openPanel($('#detailPanel'))}window.openDetail=openDetail;
function openPanel(p){p.classList.add('open');p.setAttribute('aria-hidden','false');$('#scrim').classList.add('show')}function closePanels(){$$('.detail-panel,.source-panel').forEach(p=>{p.classList.remove('open');p.setAttribute('aria-hidden','true')});$('#scrim').classList.remove('show')}$('#panelClose').onclick=closePanels;$('#sourceClose').onclick=closePanels;$('#scrim').onclick=closePanels;$('#detailPrev').onclick=()=>openDetail((activeStop+10)%11);$('#detailNext').onclick=()=>openDetail((activeStop+1)%11);
const sources=[...new Map(stops.map(s=>[s.source,s])).values()];sources.forEach((s,i)=>{$('#sourceList').insertAdjacentHTML('beforeend',`<a href="${s.source}" target="_blank" rel="noopener"><span>${String(i+1).padStart(2,'0')}</span>${s.name} · ${s.sub} ↗</a>`)});$('#sourceBtn').onclick=()=>openPanel($('#sourcePanel'));

scenarios.forEach((s,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.classList.toggle('active',i===0);b.onclick=()=>renderScenario(i);$('#scenarioTabs').append(b)});function renderScenario(i){activeScenario=i;const s=scenarios[i];$$('#scenarioTabs button').forEach((b,j)=>b.classList.toggle('active',i===j));$('#decisionBg').style.backgroundImage=`linear-gradient(90deg,#090605 5%,rgba(9,6,5,.9) 38%,rgba(9,6,5,.35)),url('${s.bg}')`;$('#decisionCard').innerHTML=`<small>${s.date}</small><h3>${s.title}</h3><p class="situation">${s.situation}</p><div class="choices">${s.choices.map((c,j)=>`<button class="choice" data-choice="${j}">${String.fromCharCode(65+j)} · ${c}</button>`).join('')}</div><div class="historical-answer"><b>${s.answer}</b><p>${s.explain}</p></div>`;$$('.choice',$('#decisionCard')).forEach(b=>b.onclick=()=>{const chosen=+b.dataset.choice;$$('.choice',$('#decisionCard')).forEach((x,j)=>{x.classList.add('reveal');if(j===s.correct)x.classList.add('correct')});b.classList.remove('reveal');$('.historical-answer',$('#decisionCard')).classList.add('show')})}renderScenario(0);

$$('#spiritPicks button').forEach(b=>b.onclick=()=>{spirit=b.dataset.spirit;$$('#spiritPicks button').forEach(x=>x.classList.toggle('active',x===b))});function refreshCard(){const text=$('#legacyText').value.trim()||'在看不清终点时，仍走好下一步。',now=new Date();$('#cardSpirit').textContent=spirit;$('#cardText').textContent=text;$('#cardDate').textContent=`${now.getFullYear()}.${String(now.getMonth()+1).padStart(2,'0')}.${String(now.getDate()).padStart(2,'0')}`;$('#cardNumber').textContent='NO. '+String(Math.floor(1000+Math.random()*8999));$('#legacyCard').classList.remove('generated');void $('#legacyCard').offsetWidth;$('#legacyCard').classList.add('generated')}$('#generateCard').onclick=refreshCard;
function wrap(ctx,text,x,y,maxWidth,lineHeight){const chars=[...text];let line='',lines=[];for(const ch of chars){if(ctx.measureText(line+ch).width>maxWidth){lines.push(line);line=ch}else line+=ch}if(line)lines.push(line);lines.slice(0,4).forEach((l,i)=>ctx.fillText(l,x,y+i*lineHeight))}
$('#downloadCard').onclick=()=>{refreshCard();const c=$('#cardCanvas'),x=c.getContext('2d');x.fillStyle='#d8ceb7';x.fillRect(0,0,1200,1600);const g=x.createLinearGradient(0,0,1200,1600);g.addColorStop(0,'rgba(255,255,255,.22)');g.addColorStop(.55,'rgba(184,137,95,.08)');g.addColorStop(1,'rgba(163,38,29,.45)');x.fillStyle=g;x.fillRect(0,0,1200,1600);x.strokeStyle='rgba(53,36,25,.36)';x.lineWidth=2;for(let i=0;i<16;i++){x.beginPath();x.moveTo(-100,i*130);x.bezierCurveTo(300,i*110-100,700,i*145+90,1300,i*120);x.stroke()}x.fillStyle='#211812';x.font='32px Space Grotesk';x.fillText('LONG MARCH · 2026',90,110);x.textAlign='right';x.fillText($('#cardNumber').textContent,1110,110);x.textAlign='left';x.strokeStyle='#6f5d49';x.beginPath();x.moveTo(90,145);x.lineTo(1110,145);x.stroke();x.fillStyle='#2c2017';x.font='36px "Noto Serif SC"';x.fillText('我的精神坐标',95,840);x.fillStyle='#a42a20';x.font='900 260px "Noto Serif SC"';x.fillText(spirit,85,1120);x.fillStyle='#251a13';x.font='700 50px "Noto Serif SC"';wrap(x,$('#legacyText').value.trim()||'在看不清终点时，仍走好下一步。',95,1245,870,72);x.strokeStyle='#9d2b22';x.lineWidth=10;x.beginPath();x.arc(965,330,118,0,Math.PI*2);x.stroke();x.save();x.translate(965,330);x.rotate(.18);x.textAlign='center';x.textBaseline='middle';x.fillStyle='#9d2b22';x.font='800 120px "Noto Serif SC"';x.fillText('征',0,0);x.restore();x.fillStyle='#30231a';x.font='28px Space Grotesk';x.fillText('从历史深处出发',95,1510);x.textAlign='right';x.fillText($('#cardDate').textContent,1110,1510);c.toBlob(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='我的长征精神坐标.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)},'image/png')};

let audioCtx,audioMaster,audioOn=false,audioBuilt=false;function buildAudio(){audioCtx=new (window.AudioContext||window.webkitAudioContext)();audioMaster=audioCtx.createGain();audioMaster.gain.value=.16;audioMaster.connect(audioCtx.destination);const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(.6+.4*Math.sin(i/40000));const noise=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter(),gain=audioCtx.createGain();noise.buffer=buffer;noise.loop=true;filter.type='lowpass';filter.frequency.value=520;gain.gain.value=.09;noise.connect(filter).connect(gain).connect(audioMaster);noise.start();[49,73.5].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=i?.025:.035;o.connect(g).connect(audioMaster);o.start()});const beat=()=>{if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime;o.frequency.setValueAtTime(68,t);o.frequency.exponentialRampToValueAtTime(45,t+.22);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.055,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.28);o.connect(g).connect(audioMaster);o.start(t);o.stop(t+.3);setTimeout(beat,2200+Math.random()*2600)};beat();audioBuilt=true}function startAudio(){if(!audioBuilt)buildAudio();audioCtx.resume();audioMaster.gain.setTargetAtTime(.16,audioCtx.currentTime,.2);audioOn=true;$('#soundBtn').classList.add('on');$('#soundBtn b').textContent='声场'}$('#soundBtn').onclick=()=>{if(!audioBuilt){startAudio();return}audioOn=!audioOn;audioMaster.gain.setTargetAtTime(audioOn?.16:.0001,audioCtx.currentTime,.15);$('#soundBtn').classList.toggle('on',audioOn);$('#soundBtn b').textContent=audioOn?'声场':'静音'};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanels();if(e.key==='ArrowRight'&&!$('#detailPanel').classList.contains('open')){const order=['prologue','route','archive','decision','legacy'];showRoom(order[Math.min(4,order.indexOf(currentRoom)+1)])}if(e.key==='ArrowLeft'&&!$('#detailPanel').classList.contains('open')){const order=['prologue','route','archive','decision','legacy'];showRoom(order[Math.max(0,order.indexOf(currentRoom)-1)])}});
